# requires: Seurat SeuratObject Matrix jsonlite digest ggplot2 patchwork
script <- normalizePath(sub("^--file=","",grep("^--file=",commandArgs(FALSE),value=TRUE)[1])); root <- normalizePath(file.path(dirname(script),"..","..","..")); mod <- file.path(root,"skills","seurat-modulescore")
source(file.path(root,"skills/_shared/scripts/module_kit.R")); source(file.path(root,"skills/_shared/scripts/handoff.R"))
scratch <- Sys.getenv("OMICSTAT_TEST_TMP","/scratch")
check <- function(ok,label) { if(!isTRUE(ok)) stop(paste("FAIL",label)); cat("PASS",label,"\n") }
run <- function(module,args) { entry <- file.path(root,"skills",module,"scripts",paste0("run_",gsub("-","_",module),".R")); log <- tempfile(tmpdir=scratch); status <- system2("Rscript",c(entry,shQuote(args)),stdout=log,stderr=log); if(status!=0) stop(paste(readLines(log),collapse="\n")); cat(paste(readLines(log),collapse="\n"),"\n") }
archive <- file.path(root,"acceptance/data/cell_cycle_vignette_files.zip")
check(digest::digest(file=archive,algo="sha256")=="6557fe2a2761d1550d41edf61b26c6d5ec9b42b4933d56c3161164a595f145ab","PACK C Nestorowa archive hash")
mat <- read.table(unz(archive,"nestorawa_forcellcycle_expressionMatrix.txt"),header=TRUE,as.is=TRUE,row.names=1)
mat <- Matrix::Matrix(as.matrix(mat),sparse=TRUE); saveRDS(mat,file.path(scratch,"marrow_counts.rds"))
library(Seurat)
sets <- list(S=cc.genes$s.genes,G2M=cc.genes$g2m.genes)
gmt <- file.path(scratch,"cell_cycle.gmt")
writeLines(vapply(names(sets),function(nm) paste(c(nm,"Seurat_5.5.1_cc.genes",sets[[nm]]),collapse="\t"),""),gmt)
qc <- file.path(scratch,"score_qc"); cluster <- file.path(scratch,"score_cluster"); out <- file.path(scratch,"score_anchor")
run("seurat-qc",c("--input",file.path(scratch,"marrow_counts.rds"),"--input-format","rds","--outdir",qc,"--organism","Mus_musculus","--feature-type","symbol","--mito-pattern","^MT-","--min-cells","0","--create-min-features","0","--min-features","0","--max-features","1000000","--min-counts","0","--max-counts","1000000000","--max-mito","100"))
# The tutorial normalizes before CellCycleScoring. Clustering is an explicit extra chain stage,
# which does not change the normalized data used for scores.
run("seurat-cluster",c("--from-run",qc,"--outdir",cluster,"--normalization","LogNormalize","--n-hvg","2000","--n-pcs","50","--dims","10","--neighbors","20","--umap-neighbors","30","--resolution","0.5","--seed","42"))
ctrl <- min(lengths(sets))
args <- c("--from-run",cluster,"--gene-sets",gmt,"--set-organism","Mus_musculus","--ctrl",as.character(ctrl),"--nbin","24","--seed","1")
run("seurat-modulescore",c(args,"--outdir",out))
x <- readRDS(file.path(out,"objects/seurat.rds")); y <- readRDS(file.path(cluster,"objects/seurat.rds"))
check(ncol(x)==774L && all(is.finite(as.matrix(x[[]][c("Cluster1","Cluster2")]))),"score output shape and finite native columns")
check(x$nCount_RNA[1]==2563089L,"PRINTED cell-cycle Prog_013 2563089 counts")
check(x$nFeature_RNA[1]==10211L,"PRINTED cell-cycle Prog_013 10211 detected features")
y <- Seurat::AddModuleScore(y,features=sets,ctrl=ctrl,nbin=24,seed=1,name="Cluster",search=FALSE,assay="RNA",slot="data")
check(identical(x$Cluster1,y$Cluster1) && identical(x$Cluster2,y$Cluster2),"REPLAY native AddModuleScore scores exact")
z <- Seurat::CellCycleScoring(y,s.features=sets$S,g2m.features=sets$G2M,set.ident=TRUE,seed=1)
check(identical(x$Cluster1,z$S.Score) && identical(x$Cluster2,z$G2M.Score),"REPLAY vignette CellCycleScoring underlying scores")
cat("OBSERVED Prog_013 scores",x$Cluster1[1],x$Cluster2[1],"archived -0.14248691 -0.4680395; ctrl",ctrl,"\n")
h <- read_handoff(out,expect=list(seurat="Seurat"),front_end_ecosystem="seurat"); check(length(h$upstream_runs)==3L && isTRUE(h$state$seurat$clustered),"real QC-cluster-score chain")
replay <- file.path(scratch,"score_replay"); run("seurat-modulescore",c("--spec",file.path(out,"provenance/resolved_spec.json"),"--outdir",replay))
check(identical(readBin(file.path(out,"tables/module_scores.csv"),"raw",1e7),readBin(file.path(replay,"tables/module_scores.csv"),"raw",1e7)),"spec replay score bytes deterministic")
if(Sys.getenv("OMICSTAT_WRITE_GOLDEN")=="1") os_golden_write(mod,out,"tables/module_scores.csv")
check(os_golden_check(mod,out)$status=="PASS","main result table golden")
source(file.path(root,"skills/_shared/scripts/calls_check.R"))
check(check_calls(list.files(file.path(mod,"scripts"),pattern="[.]R$",full.names=TRUE),file.path(mod,"scripts/calls_registry.json"))$ok,"registered calls")
check(check_default_drift(file.path(mod,"scripts/calls_registry.json"))$ok,"locked defaults")
# Prohibited collection declarations cannot enter via a user-supplied GMT.
source(file.path(root,'skills/_shared/scripts/sc_seurat_io.R'))
source(file.path(mod,'scripts/seurat_modulescore_core.R'))
for(collection in c('KEGG','CADD','PanglaoDB','DepMap')) {
 blocked <- file.path(scratch,paste0('prohibited-',collection,'.gmt'))
 writeLines(paste('synthetic_set',collection,'synthetic_gene',sep='\t'),blocked)
 aa <- list(`gene-sets`=blocked,`set-organism`='Mus_musculus')
 err <- tryCatch({seurat_modulescore_compute(x,aa);''},error=conditionMessage)
 check(grepl('OS_REFDATA_MISSING',err),paste('prohibited GMT declaration refused',collection))
}
